/// `vector.store`: writes an n-D vector to an n-D slice of memory
#[mlir::op("vector.store", format = "$valueToStore `,` $base `[` $indices `]` attr-dict `:` type($base) `,` type($valueToStore)")]
pub struct StoreOp<'a> {
    #[slot(value_to_store_ty, name = "valueToStore")]
    pub value_to_store: Value<'a>,
    #[slot(base_ty, name = "base")]
    pub base: Value<'a>,
    #[slot(indices_ty, name = "indices")]
    pub indices: Vec<Value<'a>>,
    #[attr(name = "nontemporal")]
    pub nontemporal: Option<Attribute<'a>>,
    #[attr(name = "alignment", int = "i64")]
    pub alignment: Option<Attribute<'a>>,
    #[dtype(name = "valueToStore_ty")]
    pub value_to_store_ty: Type<'a>,
    #[dtype(name = "base_ty")]
    pub base_ty: Type<'a>,
    #[dtype(name = "indices_ty", is = index)]
    pub indices_ty: Type<'a>,
}

/// `vector.to_elements`: operation that decomposes a vector into all its scalar elements
#[mlir::op("vector.to_elements", format = "$source attr-dict `:` type($source)", results(elements))]
pub struct ToElementsOp<'a> {
    #[slot(source_ty, name = "source")]
    pub source: Value<'a>,
    #[dtype(name = "source_ty")]
    pub source_ty: Type<'a>,
    #[dtype(name = "elements", el = source_ty)]
    pub elements: Vec<Type<'a>>,
}

/// `vector.transfer_read`: Reads a supervector from memory into an SSA vector value.
///
/// Generic form only (custom C++ syntax).
#[mlir::op("vector.transfer_read", generic, results(vector))]
pub struct TransferReadOp<'a> {
    #[slot(base_ty, name = "base")]
    pub base: Value<'a>,
    #[slot(indices_ty, name = "indices")]
    pub indices: Vec<Value<'a>>,
    #[slot(padding_ty, name = "padding")]
    pub padding: Value<'a>,
    #[slot(mask_ty, name = "mask")]
    pub mask: Vec<Value<'a>>,
    #[attr(name = "permutation_map")]
    pub permutation_map: Attribute<'a>,
    #[attr(name = "in_bounds")]
    pub in_bounds: Attribute<'a>,
    #[dtype(name = "base_ty")]
    pub base_ty: Type<'a>,
    #[dtype(name = "indices_ty", is = index)]
    pub indices_ty: Type<'a>,
    #[dtype(name = "padding_ty")]
    pub padding_ty: Type<'a>,
    #[dtype(name = "mask_ty")]
    pub mask_ty: Vec<Type<'a>>,
    #[dtype(name = "vector")]
    pub vector: Type<'a>,
}

/// `vector.transfer_write`: The vector.transfer_write op writes a supervector to memory.
///
/// Generic form only (custom C++ syntax).
#[mlir::op("vector.transfer_write", generic, results(result))]
pub struct TransferWriteOp<'a> {
    #[slot(value_to_store_ty, name = "valueToStore")]
    pub value_to_store: Value<'a>,
    #[slot(base_ty, name = "base")]
    pub base: Value<'a>,
    #[slot(indices_ty, name = "indices")]
    pub indices: Vec<Value<'a>>,
    #[slot(mask_ty, name = "mask")]
    pub mask: Vec<Value<'a>>,
    #[attr(name = "permutation_map")]
    pub permutation_map: Attribute<'a>,
    #[attr(name = "in_bounds")]
    pub in_bounds: Attribute<'a>,
    #[dtype(name = "valueToStore_ty")]
    pub value_to_store_ty: Type<'a>,
    #[dtype(name = "base_ty")]
    pub base_ty: Type<'a>,
    #[dtype(name = "indices_ty", is = index)]
    pub indices_ty: Type<'a>,
    #[dtype(name = "mask_ty")]
    pub mask_ty: Vec<Type<'a>>,
    #[dtype(name = "result")]
    pub result: Vec<Type<'a>>,
}

/// `vector.transpose`: vector transpose operation
#[mlir::op("vector.transpose", format = "$vector `,` $permutation attr-dict `:` type($vector) `to` type($result)", results(result))]
pub struct TransposeOp<'a> {
    #[slot(vector_ty, name = "vector")]
    pub vector: Value<'a>,
    #[attr(name = "permutation", dense = "i64")]
    pub permutation: Attribute<'a>,
    #[dtype(name = "vector_ty")]
    pub vector_ty: Type<'a>,
    #[dtype(name = "result")]
    pub result: Type<'a>,
}

/// `vector.type_cast`: type_cast op converts a scalar memref to a vector memref
#[mlir::op("vector.type_cast", format = "$memref attr-dict `:` type($memref) `to` type($result)", results(result))]
pub struct TypeCastOp<'a> {
    #[slot(memref_ty, name = "memref")]
    pub memref: Value<'a>,
    #[dtype(name = "memref_ty")]
    pub memref_ty: Type<'a>,
    #[dtype(name = "result")]
    pub result: Type<'a>,
}

/// `vector.yield`: Terminates and yields values from vector regions.
#[mlir::op("vector.yield", format = "attr-dict ($operands^ `:` type($operands))?")]
pub struct YieldOp<'a> {
    #[slot(operands_ty, name = "operands")]
    pub operands: Vec<Value<'a>>,
    #[dtype(name = "operands_ty")]
    pub operands_ty: Vec<Type<'a>>,
}

/// The `vector` dialect.
#[mlir::dialect("vector")]
pub enum Vector<'a> {
    VectorScale(VectorScaleOp<'a>),
    BitCast(BitCastOp<'a>),
    Broadcast(BroadcastOp<'a>),
    CompressStore(CompressStoreOp<'a>),
    ConstantMask(ConstantMaskOp<'a>),
    Contraction(ContractionOp<'a>),
    CreateMask(CreateMaskOp<'a>),
    Deinterleave(DeinterleaveOp<'a>),
    ExpandLoad(ExpandLoadOp<'a>),
    Extract(ExtractOp<'a>),
    ExtractStridedSlice(ExtractStridedSliceOp<'a>),
    FMA(FMAOp<'a>),
    FromElements(FromElementsOp<'a>),
    Gather(GatherOp<'a>),
    Insert(InsertOp<'a>),
    InsertStridedSlice(InsertStridedSliceOp<'a>),
    Interleave(InterleaveOp<'a>),
    Load(LoadOp<'a>),
    Mask(MaskOp<'a>),
    MaskedLoad(MaskedLoadOp<'a>),
    MaskedStore(MaskedStoreOp<'a>),
    MultiDimReduction(MultiDimReductionOp<'a>),
    OuterProduct(OuterProductOp<'a>),
    Print(PrintOp<'a>),
    Reduction(ReductionOp<'a>),
    ScalableExtract(ScalableExtractOp<'a>),
    ScalableInsert(ScalableInsertOp<'a>),
    Scan(ScanOp<'a>),
    Scatter(ScatterOp<'a>),
    ShapeCast(ShapeCastOp<'a>),
    Shuffle(ShuffleOp<'a>),
    Step(StepOp<'a>),
    Store(StoreOp<'a>),
    ToElements(ToElementsOp<'a>),
    TransferRead(TransferReadOp<'a>),
    TransferWrite(TransferWriteOp<'a>),
    Transpose(TransposeOp<'a>),
    TypeCast(TypeCastOp<'a>),
    Yield(YieldOp<'a>),
}
